import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"相机工具","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"zh/qgc-user-guide/fly_view/camera_tools.md","filePath":"zh/qgc-user-guide/fly_view/camera_tools.md"}`),a={name:`zh/qgc-user-guide/fly_view/camera_tools.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="相机工具" tabindex="-1">相机工具 <a class="header-anchor" href="#相机工具" aria-label="Permalink to “相机工具”">​</a></h1><p>相机工具用于拍摄静态图像和视频，以及对相机进行配置。</p><p>相机捕获和配置选项取决于已连接的相机。配置选项是使用面板装备图标选择的。一个简单的自动化摄像头的配置显示在下面。</p><p>当连接到支持<a href="https://mavlink.io/en/services/camera.html" target="_blank" rel="noreferrer">MAVLink 相机协议</a>的相机时，您可以另外配置和使用它提供的其他相机服务。例如，如果您的摄像头支持视频模式，您将能够在仍然存在的图像捕获和视频模式之间切换，并且开始/停止录制。</p><p>::: 信息 所显示的大多数设置都依赖摄像头(它们是在 <a href="https://mavlink.io/en/services/camera_def.html" target="_blank" rel="noreferrer">MAVLink 相机定义文件</a> 中定义的)。</p><blockquote><p>A few common settings at the end are hard-coded: Photo Mode (Single/Time Lapse), Photo Interval (if Time Lapse), Reset Camera Defaults (sends a reset command to the camera), Format (storage), and for a camera with a video stream, Grid Lines, Telemetry Overlay and Display Fit (under Video Display) :::</p></blockquote><h2 id="video_instrument_page" tabindex="-1">视频流 <a class="header-anchor" href="#video_instrument_page" aria-label="Permalink to “视频流”">​</a></h2><p>视频页面用于启用/禁用视频流。 When enabled, you can start/stop the video stream, enable a grid overlay or the <a href="./video_overlay.html#live-overlay">live telemetry overlay</a>, change how the image fits the screen, and record the video locally with QGC.</p><p>A single photo the camera can&#39;t take itself (it can&#39;t capture images, or not in video mode) is saved by QGC instead, from the video on display, to the <code>Photo</code> folder of the <a href="./../settings_view/general.html#load-save-path">Application Load/Save Path</a>. The JPEG records when it was taken and where the vehicle was (EXIF date and GPS position).</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};